/// `.github/workflows/dashcrew.yml`: runs `dashcrew check` on every pull request, with dashcrew pinned at [dashcrewRef]
/// so CI judges a PR with the same dashcrew the team uses. Make its `check` job a required status check.
String githubWorkflow(String dashcrewRef) => '''
# Generated by dashcrew sync. Change ci in .ai/project.yaml and run dashcrew sync instead of editing this file.
name: dashcrew check

on:
  pull_request:
    types: [opened, edited, synchronize, reopened]

permissions:
  contents: read
  pull-requests: read

jobs:
  check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-go@v5
        with:
          go-version: stable
          cache: false
      - run: go install github.com/fahnaladitia/dashcrew/cmd/dashcrew@$dashcrewRef
      - run: dashcrew check
''';
